station_modules = [
  ['Oxygen Generator', 'Water Reclaimer'],
  ['Solar Panel Array', 'Communications Dish', 'Radar'],
  ['Engine Core', 'Navigation Computer']
]

system_codes = [
  ['NOMINAL', 'NOMINAL', 'FAULTY'],
  ['NOMINAL', 'NOMINAL'],
  ['NOMINAL', 'NOMINAL', 'NOMINAL']
]

# 1. Print station coordinates (0-2, 0-3):
for x in range(3):
    for y in range(4):
        print('Station at (', x, ',', y, ')')

# 2. Print all equipment in station_modules:
for module in station_modules:
    for equipment in module:
        print(equipment)

# 3. Scan for faulty systems with break:
for module_idx, module in enumerate(system_codes):
    print('Scanning Module', module_idx, '...')
    for system in module:
        print('Checking system:', system)
        if system == 'FAULTY':
            print('⚠️ Fault detected!')
            break

