import ast

# Parse the code
tree = ast.parse(code)

# Count nested loops
nested_pairs = 0
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        # Check if this for loop contains another for loop
        for child in ast.walk(node):
            if isinstance(child, ast.For) and child != node:
                # Make sure it's a direct child
                # Simple check: if we find a For inside a For, count it
                nested_pairs += 1
                break  # Count each outer loop only once

assert nested_pairs >= 3, f'Should have at least 3 nested loop pairs, got {nested_pairs}'

# Check for break statement in nested loop
break_in_nested = False
for node in ast.walk(tree):
    if isinstance(node, ast.Break):
        # Check if this break is inside a loop that's inside another loop
        current = node
        loop_depth = 0
        while hasattr(current, 'parent'):
            current = current.parent
            if isinstance(current, ast.For):
                loop_depth += 1
                if loop_depth >= 2:
                    break_in_nested = True
                    break
        # Simple parent check
        if not break_in_nested:
            # Check ancestors
            for ancestor in ast.walk(tree):
                if isinstance(ancestor, ast.For):
                    for child in ast.walk(ancestor):
                        if child == node:
                            # Node is inside this for loop
                            # Now check if ancestor itself is inside another for
                            for grand_ancestor in ast.walk(tree):
                                if isinstance(grand_ancestor, ast.For) and grand_ancestor != ancestor:
                                    for grand_child in ast.walk(grand_ancestor):
                                        if grand_child == ancestor:
                                            break_in_nested = True
                                            break

assert break_in_nested, 'Should use break inside a nested loop (inner loop)'

print('TEST_PASSED: Correct nested loop structure with break')
